void sortStringArray(std::string arr[], int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (arr[i] > arr[j]) {
                swapStrings(arr[i], arr[j]);
            }
        }
    }
}

